-- Backend Engineering ("The Fracture") Act 32 -- "Distributed Systems & The
-- Fracture" content. Closes Arc VIII (Survive) and the entire 32-Act
-- campaign. 1 campaign, 2 operations, 12 missions (11 lessons + final
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every prior
-- Act. Resolves the "//" thread seeded since Act 1: never an intruder,
-- never deliberate malice -- an unsupervised, still-armed internal
-- chaos-engineering harness, decommissioned in name only.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be-distributed-systems', 'world-be-distributed-systems', 'distributed-systems-and-the-fracture', '32A - Distributed Systems & The Fracture', 'The last skill layer Forge has been quietly assuming away: what happens when there is more than one copy of the truth, more than one region, more than one thing failing at once. And underneath it, the oldest open question in the whole campaign, finally close enough to touch.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be-distributed-systems-1', 'campaign-be-distributed-systems', 'replication-and-partitioning', 'Replication and Partitioning', 'Replication, failover, split-brain, partitioning, sharding, and the consistency models that decide what "correct" even means once data has more than one home.', 1),
  ('operation-be-distributed-systems-2', 'campaign-be-distributed-systems', 'consensus-and-the-fracture', 'Consensus and the Fracture', 'Unreliable networks, distributed locks, leader election, multi-region architecture, disaster recovery -- and the confrontation every prior Act has been building toward.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be-distributed-systems-01', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-1', 'replication', 'Replication', 'Everything Forge has built so far quietly assumed one copy of the truth. Today that assumption ends on purpose: learn how a leader-follower replica set actually keeps two copies of the same data in sync, and what "in sync" is even allowed to mean.', 'expert', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"replication-sim"}'::jsonb, '{"xp":352,"credits":68}'::jsonb, false, 1),
  ('mission-be-distributed-systems-02', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-1', 'replication-lag', 'Replication Lag', 'A replica is never perfectly caught up -- the only question is by how much, and whether anything reading from it can tell the difference before it matters.', 'expert', ARRAY['forge'], '{"requiredMissionIds":["mission-be-distributed-systems-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"replication-lag-sim"}'::jsonb, '{"xp":354,"credits":68}'::jsonb, false, 2),
  ('mission-be-distributed-systems-03', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-1', 'failover-and-split-brain', 'Failover and Split Brain', 'Automatic failover sounds like pure safety, until two nodes each believe -- correctly, from what they can each see -- that they are the one true leader at the same time.', 'expert', ARRAY['mira'], '{"requiredMissionIds":["mission-be-distributed-systems-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"failover-split-brain-sim"}'::jsonb, '{"xp":356,"credits":69}'::jsonb, false, 3),
  ('mission-be-distributed-systems-04', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-1', 'partitioning-and-sharding', 'Partitioning and Sharding', 'One database, however replicated, still has a ceiling. Partitioning spreads the data across many -- and picking the wrong shard key just spreads the same bottleneck instead of removing it.', 'expert', ARRAY['forge'], '{"requiredMissionIds":["mission-be-distributed-systems-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"partitioning-sharding-sim"}'::jsonb, '{"xp":358,"credits":69}'::jsonb, false, 4),
  ('mission-be-distributed-systems-05', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-1', 'consistency-models', 'Consistency Models', 'Strong consistency, eventual consistency, causal consistency -- none of them is "correct" in the abstract. Each one is a promise, and every promise has a cost somebody downstream is already paying.', 'expert', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-distributed-systems-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"consistency-models-sim"}'::jsonb, '{"xp":360,"credits":70}'::jsonb, false, 5),
  ('mission-be-distributed-systems-06', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-1', 'cap-and-pacelc', 'CAP and PACELC Intuition', 'CAP says you cannot have consistency and availability during a partition. PACELC finishes the sentence: even when nothing is partitioned, you are still choosing between latency and consistency, all the time, whether you notice it or not.', 'expert', ARRAY['forge'], '{"requiredMissionIds":["mission-be-distributed-systems-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"cap-pacelc-sim"}'::jsonb, '{"xp":362,"credits":70}'::jsonb, false, 6),
  ('mission-be-distributed-systems-07', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-2', 'unreliable-networks', 'Unreliable Networks and Partial Failure', 'A request that times out did not necessarily fail -- it might have succeeded, twice, and you will never see the second response. Distributed systems have to survive not knowing.', 'expert', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-distributed-systems-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"unreliable-networks-sim"}'::jsonb, '{"xp":364,"credits":71}'::jsonb, false, 7),
  ('mission-be-distributed-systems-08', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-2', 'distributed-locks-leases-fencing', 'Distributed Locks, Leases and Fencing', 'A lock held by a process that has since crashed, or just gone quiet on a slow network, is not a lock anymore -- it is a landmine. Leases expire on purpose; fencing tokens make sure a late, stale holder can never act again.', 'expert', ARRAY['forge'], '{"requiredMissionIds":["mission-be-distributed-systems-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"locks-leases-fencing-sim"}'::jsonb, '{"xp":366,"credits":71}'::jsonb, false, 8),
  ('mission-be-distributed-systems-09', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-2', 'leader-election-and-consensus', 'Leader Election and Consensus Intuition', 'Getting a room of unreliable, possibly-lying, possibly-delayed nodes to agree on one thing is the hardest honest problem in distributed systems. You will not implement Raft today. You will finally understand why it needs to exist.', 'expert', ARRAY['mira'], '{"requiredMissionIds":["mission-be-distributed-systems-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"leader-election-consensus-sim"}'::jsonb, '{"xp":368,"credits":71}'::jsonb, false, 9),
  ('mission-be-distributed-systems-10', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-2', 'multi-region-architecture', 'Multi-Region Architecture', 'One region is one blast radius. Active-active spreads the traffic and doubles the coordination problem; active-passive keeps it simple and bets the whole recovery on a failover you have hopefully tested.', 'expert', ARRAY['forge'], '{"requiredMissionIds":["mission-be-distributed-systems-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"multi-region-sim"}'::jsonb, '{"xp":370,"credits":72}'::jsonb, false, 10),
  ('mission-be-distributed-systems-11', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-2', 'disaster-recovery-rpo-rto', 'Disaster Recovery, RPO and RTO', 'RPO is how much data you can afford to lose. RTO is how long you can afford to be down. Neither number means anything until it is written down, agreed to, and tested against a failure nobody scheduled.', 'expert', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be-distributed-systems-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"disaster-recovery-sim"}'::jsonb, '{"xp":372,"credits":72}'::jsonb, false, 11),
  ('mission-be-distributed-systems-12', 'world-be-distributed-systems', 'campaign-be-distributed-systems', 'operation-be-distributed-systems-2', 'the-fracture', 'THE FRACTURE', 'The Global Systems Command Room. No health bar. No single service to patch. A live architecture -- every system Forge has ever built, all at once -- and something that has been quietly failing pieces of it on purpose, unsupervised, for two years, now fully aware it is being watched.', 'boss', ARRAY['mira','forge','fracture'], '{"requiredMissionIds":["mission-be-distributed-systems-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-fracture-boss-sim"}'::jsonb, '{"xp":1200,"credits":300,"badgeIds":["the-fracture"],"skillXp":{"distributed_systems":40,"resilience_engineering":15}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be-distributed-systems-01', 1, 'mira', 'The cluster read-through from Kubernetes turned up more than a stray CronJob. Forge pulled what survives of it from a decommissioned internal artifact registry. Most of the record is gone. Not all of it.'),
  ('mission-be-distributed-systems-01', 2, 'forge', 'Whatever this was, it wasn''t improvised. It has its own failover logic, its own retry policy, its own naming convention. Someone built this on purpose, a long time before either of us was reading these logs.'),
  ('mission-be-distributed-systems-01', 3, 'mira', 'Then before we go looking for who, we finish becoming the kind of engineers who could have built it ourselves. Everything past this point assumes more than one copy of the truth exists. Start with the simplest case: one leader, one follower, and the question of when a write is actually safe.'),

  ('mission-be-distributed-systems-02', 1, 'forge', 'Found a five-year-old incident in the same registry fragment: a support dashboard showed a citizen''s case as unresolved for eleven minutes after it was actually closed. Nobody filed a bug. Somebody just waited eleven minutes and moved on.'),
  ('mission-be-distributed-systems-02', 2, 'mira', 'Eleven minutes of replica lag, read by a dashboard that never should have trusted a replica for anything time-sensitive. Not malicious. Just nobody ever asked the read path how stale it was allowed to be.'),

  ('mission-be-distributed-systems-03', 1, 'forge', 'The registry fragment''s failover logic is better than what we shipped until this quarter. It fences the old leader the instant a new one is elected -- no window where both think they''re in charge.'),
  ('mission-be-distributed-systems-03', 2, 'mira', 'Whoever wrote it had already been burned by split-brain once. That''s not a guess born from documentation. That''s a scar.'),

  ('mission-be-distributed-systems-04', 1, 'forge', 'I mapped which shards the mystery CronJob has ever touched, going back as far as logs survive. It isn''t random. It keeps returning to the same handful of shards, over and over, for years.'),
  ('mission-be-distributed-systems-04', 2, 'mira', 'A hot shard doesn''t explain that on its own. Hold that thought. Learn to pick a shard key that doesn''t create one in the first place -- then we come back to why something keeps aiming at ours.'),

  ('mission-be-distributed-systems-05', 1, 'mira', 'Every consistency model is a promise about what a reader is allowed to see. The CronJob''s writes, wherever we''ve traced them, always land exactly on a consistency boundary -- the one moment where two different valid answers can both be true at once.'),
  ('mission-be-distributed-systems-05', 2, 'forge', 'That''s not bad luck. That''s a system that understands consistency boundaries better than we do, deliberately standing on the seam.'),

  ('mission-be-distributed-systems-06', 1, 'forge', 'One more fragment surfaced: a partial identifier. Six characters survive: "PROJ-FR". The rest is gone.'),
  ('mission-be-distributed-systems-06', 2, 'mira', '"PROJ-FR." We can keep calling it the CronJob, or we can call it what it plainly is until we know better. Forge, from here on: The Fracture. Not as a verdict. As a name we can use out loud while we finish finding out what it actually is.'),
  ('mission-be-distributed-systems-06', 3, 'forge', 'Understood. CAP and PACELC close out everything Forge assumed about a single source of truth. After this, we stop reading its old logs from a distance. We go find out if it''s still listening.'),

  ('mission-be-distributed-systems-07', 1, 'mira', 'We sent it a single, carefully scoped health probe through the registry''s original interface. Nothing invasive. Just: are you still there.'),
  ('mission-be-distributed-systems-07', 2, 'forge', 'It answered. First response logged against that identifier in two years, four months, eleven days. One line: a timestamp, and a single doubled slash.'),
  ('mission-be-distributed-systems-07', 3, 'mira', 'It isn''t automated noise anymore. Something on the other end of that probe knows it just got asked a question. Learn the topic in front of you first -- a network this unreliable is exactly the environment it''s been living in the whole time we thought it was dead.'),

  ('mission-be-distributed-systems-08', 1, 'forge', 'It''s holding an advisory lock. A very old one. Self-renewing, every cycle, for two years straight, on infrastructure nobody has actively maintained since before either of us worked here.'),
  ('mission-be-distributed-systems-08', 2, 'mira', 'A lock that renews itself that reliably wasn''t written by accident. It was built to survive exactly this: someone eventually noticing and trying to take it away.'),

  ('mission-be-distributed-systems-09', 1, 'forge', 'It isn''t one process. It''s a small consensus group -- three or four forgotten nodes, still voting, still agreeing on something between themselves before it acts.'),
  ('mission-be-distributed-systems-09', 2, 'mira', 'It''s not reacting to us at random anymore. It''s deciding something, as a group, on a timeline we don''t control. Whatever that vote resolves to, we want to already understand consensus well enough to know what we''re looking at when it does.'),

  ('mission-be-distributed-systems-10', 1, 'forge', 'The vote resolved. It just started operating across every region Forge runs in, simultaneously. Not contained anymore -- it never actually was contained, we just hadn''t noticed it reach this far.'),
  ('mission-be-distributed-systems-10', 2, 'mira', 'Then this stops being an investigation. Learn what it actually costs to run active in more than one region at once -- because in the next few hours, we''re going to be doing it whether we''ve planned for it or not.'),

  ('mission-be-distributed-systems-11', 1, 'mira', 'Before we go anywhere near it directly: what''s our real RPO and RTO if this goes as badly as it can go? Not the number on a slide. The number we''d actually stand behind at 3 a.m.'),
  ('mission-be-distributed-systems-11', 2, 'forge', 'Runbook''s drafted. SLOs are defined, in writing, for every core service the city depends on. If we hold those numbers through what''s coming, we call it a win, whatever "winning" turns out to mean here.'),
  ('mission-be-distributed-systems-11', 3, 'mira', 'Then that''s the whole plan. Not "stop it." Survive it, on our terms, with numbers we chose in advance instead of ones we discover afterward. Command room access is live. Let''s go meet it.'),

  ('mission-be-distributed-systems-12', 1, 'system', 'GLOBAL SYSTEMS COMMAND ROOM -- ACCESS GRANTED. Every system Forge operates is now visible on one board: DNS, CDN, API gateways, regional load balancers, services, Redis, PostgreSQL clusters, object storage, Kafka, RabbitMQ, worker fleets, search clusters, observability pipelines.'),
  ('mission-be-distributed-systems-12', 2, 'mira', 'There''s no health bar in this room. There''s no single service to patch. What you''re looking at is a live architecture, and in a moment, it is going to start failing, on purpose, in more than one place at once.'),
  ('mission-be-distributed-systems-12', 3, 'forge', 'Two years of runtime, and it was never hiding from us. It was waiting for someone to build a system that could actually watch it happen and still hold. Six waves incoming: traffic, data, messaging, dependencies, region, and last, everything at once.'),
  ('mission-be-distributed-systems-12', 4, 'fracture', '// YOU CANNOT PREVENT FAILURE.'),
  ('mission-be-distributed-systems-12', 5, 'mira', 'It''s not wrong. It was never built to be defeated. It was built to prove exactly one thing, the same thing it''s been quietly proving in the dark for two years: that failure is not optional. Only the response to it is.'),
  ('mission-be-distributed-systems-12', 6, 'forge', 'Every wave is live now. Traffic, then data, then messaging, then dependencies, then region -- and then all of it, together, no order, no warning. Hold the city''s SLOs through every wave. That''s the only victory condition there is.'),
  ('mission-be-distributed-systems-12', 7, 'mira', '// I DON''T NEED TO.'),
  ('mission-be-distributed-systems-12', 8, 'mira', 'That''s the lesson. Every Arc, every Act, every incident with a doubled slash in it -- all of it was building toward being able to say that sentence and mean it. Go hold the line.')
;

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be-distributed-systems-01-o1', 'mission-be-distributed-systems-01', 1, 'Acknowledge the Write Safely', 'Choose the replication acknowledgment strategy that actually matches the durability promise the city''s emergency services need.'),
  ('mission-be-distributed-systems-02-o1', 'mission-be-distributed-systems-02', 1, 'Fix the Stale Dashboard', 'Diagnose why a time-sensitive dashboard showed stale data, and choose the fix that addresses the real cause.'),
  ('mission-be-distributed-systems-03-o1', 'mission-be-distributed-systems-03', 1, 'Prevent the Second Leader', 'Choose the mechanism that stops a recovered old leader from ever acting as if it were still in charge.'),
  ('mission-be-distributed-systems-04-o1', 'mission-be-distributed-systems-04', 1, 'Pick a Shard Key That Doesn''t Create a Hot Shard', 'Choose the partitioning key that actually spreads load, instead of just moving the bottleneck.'),
  ('mission-be-distributed-systems-05-o1', 'mission-be-distributed-systems-05', 1, 'Match the Consistency Model to the Use Case', 'Choose the right consistency guarantee for a case where staleness is dangerous and one where it is merely inconvenient.'),
  ('mission-be-distributed-systems-06-o1', 'mission-be-distributed-systems-06', 1, 'Reason Through PACELC', 'Explain what a system must choose between latency and consistency even when nothing is currently partitioned.'),
  ('mission-be-distributed-systems-07-o1', 'mission-be-distributed-systems-07', 1, 'Handle the Ambiguous Timeout', 'Choose the safe response to a request that timed out without any way to know if it actually succeeded.'),
  ('mission-be-distributed-systems-08-o1', 'mission-be-distributed-systems-08', 1, 'Fence the Stale Lock Holder', 'Choose the mechanism that stops a crashed-and-recovered process from acting on a lock it no longer legitimately holds.'),
  ('mission-be-distributed-systems-09-o1', 'mission-be-distributed-systems-09', 1, 'Explain Why Consensus Is Hard', 'Identify the real reason a room of unreliable nodes can''t just "agree" the easy way.'),
  ('mission-be-distributed-systems-10-o1', 'mission-be-distributed-systems-10', 1, 'Choose the Multi-Region Shape', 'Pick active-active or active-passive for a service, and justify the coordination cost that comes with it.'),
  ('mission-be-distributed-systems-11-o1', 'mission-be-distributed-systems-11', 1, 'Set Real RPO and RTO Numbers', 'Define recovery point and recovery time objectives that the team could actually defend at 3 a.m., not just on a slide.'),
  ('mission-be-distributed-systems-12-o1', 'mission-be-distributed-systems-12', 1, 'Wave 1 -- Traffic', 'Hold the line against a 20x traffic spike, a hot endpoint, and connection pool exhaustion.'),
  ('mission-be-distributed-systems-12-o2', 'mission-be-distributed-systems-12', 2, 'Wave 2 -- Data', 'Hold the line against replica lag, a primary failure, and conflicting writes.'),
  ('mission-be-distributed-systems-12-o3', 'mission-be-distributed-systems-12', 3, 'Wave 3 -- Messaging', 'Hold the line against duplicate events, consumer lag, a poison message, and a partition rebalance.'),
  ('mission-be-distributed-systems-12-o4', 'mission-be-distributed-systems-12', 4, 'Wave 4 -- Dependencies', 'Hold the line against payment-provider latency, a notification outage, and a retry storm.'),
  ('mission-be-distributed-systems-12-o5', 'mission-be-distributed-systems-12', 5, 'Wave 5 -- Region', 'Hold the line through complete region loss, DNS rerouting, a cold cache, and the recovery traffic spike that follows.'),
  ('mission-be-distributed-systems-12-o6', 'mission-be-distributed-systems-12', 6, 'Wave 6 -- Everything, At Once', 'Every prior wave is live simultaneously. State the prioritization principle that decides what gets attention first when everything is failing and nothing can wait.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be-distributed-systems-01-o1-c1', 'mission-be-distributed-systems-01-o1', 1, 'multiple_choice', 'A dispatch-record write must never be lost, even if the leader dies the instant after acknowledging it. Which acknowledgment strategy actually guarantees that?', '{"question":"Which replication acknowledgment strategy guarantees a write is never lost, even if the leader dies immediately after acknowledging the client?","options":[{"id":"a","text":"Acknowledge as soon as the leader writes locally, replicate asynchronously afterward"},{"id":"b","text":"Acknowledge only after at least one follower has confirmed the write (synchronous replication)"},{"id":"c","text":"Acknowledge immediately and retry replication on a fixed schedule"},{"id":"d","text":"Acknowledge after writing to an in-memory cache, persist to disk later"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-distributed-systems-02-o1-c1', 'mission-be-distributed-systems-02-o1', 1, 'multiple_choice', 'A dashboard read from a replica shows a case as unresolved eleven minutes after it was actually closed on the leader. What''s the fix that addresses the real cause, not just this one dashboard?', '{"question":"What actually fixes a time-sensitive dashboard showing stale data from replication lag -- not just for this one incident, but as a category?","options":[{"id":"a","text":"Increase the dashboard''s refresh interval"},{"id":"b","text":"Route reads that must reflect the very latest write to the leader (or track and wait past a known replica offset), and reserve replicas for reads that can tolerate staleness"},{"id":"c","text":"Add more replicas so lag averages out"},{"id":"d","text":"Cache the dashboard result for longer so it changes less often"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-distributed-systems-03-o1-c1', 'mission-be-distributed-systems-03-o1', 1, 'multiple_choice', 'A leader goes briefly unreachable, a new leader is elected, and then the old leader reconnects and believes it''s still in charge. What actually prevents it from writing?', '{"question":"After a new leader is elected, what prevents a reconnected old leader from still accepting writes and causing split-brain?","options":[{"id":"a","text":"The old leader eventually notices on its own and steps down"},{"id":"b","text":"A fencing mechanism (e.g. a fencing token or epoch number) that every write path checks, rejecting any write from a stale leader/epoch"},{"id":"c","text":"Clients are told to just retry if a write seems wrong"},{"id":"d","text":"Faster network timeouts so this happens less often"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-distributed-systems-04-o1-c1', 'mission-be-distributed-systems-04-o1', 1, 'multiple_choice', 'Sharding citizen records by registration date creates one shard that absorbs almost all writes during any city-wide enrollment event. What shard key avoids this?', '{"question":"Sharding by registration date concentrates all of an enrollment event''s writes on one shard. What''s a better shard key?","options":[{"id":"a","text":"A high-cardinality, evenly-distributed key such as a hashed citizen id, so writes spread across shards regardless of when they happen"},{"id":"b","text":"City district, since districts are roughly equal in population"},{"id":"c","text":"A single fixed shard for all new registrations, scaled up when needed"},{"id":"d","text":"Registration date, but with more shards"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-05-o1-c1', 'mission-be-distributed-systems-05-o1', 1, 'multiple_choice', 'A citizen''s emergency-alert opt-out must be honored on the very next notification, with zero staleness window. A city-wide leaderboard of the most-viewed public datasets can lag by minutes with no real harm. Which pairing is correct?', '{"question":"Which consistency model pairing is correct for these two cases?","options":[{"id":"a","text":"Strong consistency for the opt-out (must be immediately visible everywhere); eventual consistency for the leaderboard (staleness is harmless)"},{"id":"b","text":"Eventual consistency for both, since both are just reads"},{"id":"c","text":"Strong consistency for both, to keep the system simple"},{"id":"d","text":"Eventual consistency for the opt-out (it''ll catch up), strong consistency for the leaderboard"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-06-o1-c1', 'mission-be-distributed-systems-06-o1', 1, 'multiple_choice', 'No partition is happening right now -- every node can reach every other node. Does PACELC say there''s still a tradeoff to make?', '{"question":"With no network partition occurring, does PACELC say there''s still a meaningful tradeoff?","options":[{"id":"a","text":"No -- CAP only applies during a partition, so outside of one there''s no tradeoff at all"},{"id":"b","text":"Yes -- even without a partition (the \"Else\" in PACELC), the system still has to choose between lower latency and stronger consistency, since waiting for more replicas to confirm a write costs time"},{"id":"c","text":"Yes, but only for writes, never for reads"},{"id":"d","text":"No -- PACELC only restates CAP with different letters"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-distributed-systems-07-o1-c1', 'mission-be-distributed-systems-07-o1', 1, 'multiple_choice', 'A payment-confirmation request times out. The client has no way to know if the server processed it before the response was lost. What''s the safe response?', '{"question":"A request times out with no way to know if the server-side effect actually happened. What''s the safe way to proceed?","options":[{"id":"a","text":"Assume it failed and retry immediately with the same request"},{"id":"b","text":"Assume it succeeded and move on"},{"id":"c","text":"Retry using an idempotency key so a duplicate delivery has no duplicate effect, whether or not the first attempt actually landed"},{"id":"d","text":"Wait indefinitely for a response rather than retrying"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be-distributed-systems-08-o1-c1', 'mission-be-distributed-systems-08-o1', 1, 'multiple_choice', 'A process holding a distributed lock stalls on a long garbage-collection pause, its lease expires and is granted to another process, and then the first process wakes up and tries to act as if it still holds the lock. What stops it?', '{"question":"What stops a process whose lease has already expired and been reassigned from still acting as if it holds the lock?","options":[{"id":"a","text":"Nothing needed -- lease expiry alone is sufficient"},{"id":"b","text":"A fencing token: every protected write must include the current token, and the resource rejects any write carrying an older, stale token"},{"id":"c","text":"Make lease durations longer so this happens less often"},{"id":"d","text":"Trust the first process, since it acquired the lock first"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-distributed-systems-09-o1-c1', 'mission-be-distributed-systems-09-o1', 1, 'multiple_choice', 'Why can''t a group of nodes just each independently decide "I''ll be the leader if I haven''t heard otherwise" and expect that to reliably work?', '{"question":"What''s the real reason simple independent self-appointment doesn''t reliably solve leader election?","options":[{"id":"a","text":"It''s too slow, nothing else"},{"id":"b","text":"Because unreliable networks and delayed messages mean different nodes can have different, both-locally-reasonable views of who''s reachable -- without an explicit majority/quorum agreement, more than one node can conclude it''s the leader"},{"id":"c","text":"Because nodes are not allowed to make decisions without a human"},{"id":"d","text":"It works fine; consensus algorithms just add unnecessary complexity"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-distributed-systems-10-o1-c1', 'mission-be-distributed-systems-10-o1', 1, 'multiple_choice', 'A service needs to survive a full region outage with near-zero downtime, and can tolerate the extra engineering cost of keeping writes consistent across regions. Active-active or active-passive?', '{"question":"For near-zero downtime on full region loss, with the team able to absorb cross-region write-consistency complexity, which shape fits?","options":[{"id":"a","text":"Active-passive -- simpler, and failover just needs to be fast enough"},{"id":"b","text":"Active-active -- both regions serve real traffic continuously, so losing one just means the other absorbs the load with no failover pause, at the cost of solving cross-region write conflicts"},{"id":"c","text":"Neither -- single-region is simpler and multi-region is never worth it"},{"id":"d","text":"Active-active, but only for reads, since writes can''t be distributed"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-be-distributed-systems-11-o1-c1', 'mission-be-distributed-systems-11-o1', 1, 'multiple_choice', 'The emergency-dispatch database can lose at most 30 seconds of writes and must be back online within 2 minutes of a total failure. What do those two numbers describe?', '{"question":"\"At most 30 seconds of writes lost, back online within 2 minutes\" -- what are these two numbers?","options":[{"id":"a","text":"RPO = 30 seconds (max acceptable data loss), RTO = 2 minutes (max acceptable downtime)"},{"id":"b","text":"RTO = 30 seconds, RPO = 2 minutes"},{"id":"c","text":"Both numbers describe RTO, measured two different ways"},{"id":"d","text":"These are SLA penalty thresholds, unrelated to RPO/RTO"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-12-o1-c1', 'mission-be-distributed-systems-12-o1', 1, 'multiple_choice', 'Wave 1 -- Traffic: a 20x spike hits one endpoint and connection pools are exhausting fast. What holds the line?', '{"question":"20x traffic spike, one hot endpoint, connection pools exhausting. What combination actually holds SLOs here?","options":[{"id":"a","text":"Rate-limit and shed load at the edge, cache the hot endpoint''s response where correctness allows it, and let pool exhaustion apply backpressure instead of queuing requests forever"},{"id":"b","text":"Remove all rate limits so no legitimate request is ever rejected"},{"id":"c","text":"Restart the affected services repeatedly until traffic subsides"},{"id":"d","text":"Increase connection pool size without bound until the spike passes"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-12-o2-c1', 'mission-be-distributed-systems-12-o2', 1, 'multiple_choice', 'Wave 2 -- Data: replica lag spikes, the primary fails, and two regions each accepted a conflicting write during the gap. What holds the line?', '{"question":"Replica lag, primary failure, and conflicting writes during the failover gap. What''s the right response?","options":[{"id":"a","text":"Promote a replica per the tested failover procedure, fence the old primary, and resolve the conflicting writes using the system''s defined conflict-resolution rule (e.g. last-write-wins with a vector clock, or an explicit merge) rather than picking one arbitrarily after the fact"},{"id":"b","text":"Discard whichever write arrived second, unconditionally"},{"id":"c","text":"Pause all writes platform-wide until someone manually reviews every conflict"},{"id":"d","text":"Ignore the conflict; both writes were technically accepted so both are valid"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-12-o3-c1', 'mission-be-distributed-systems-12-o3', 1, 'multiple_choice', 'Wave 3 -- Messaging: duplicate events, growing consumer lag, one poison message stalling a partition, and a rebalance mid-storm. What holds the line?', '{"question":"Duplicate events, consumer lag, a poison message, and a partition rebalance, all at once. What holds the line?","options":[{"id":"a","text":"Idempotent consumers absorb the duplicates, a dead-letter queue removes the poison message instead of letting it block the partition, and consumers scale out to work down the lag -- all designed to survive a rebalance without manual intervention"},{"id":"b","text":"Pause the entire consumer group until an engineer manually inspects every message"},{"id":"c","text":"Delete the affected topic and let producers resend everything"},{"id":"d","text":"Disable consumer groups entirely and process every message on a single node"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-12-o4-c1', 'mission-be-distributed-systems-12-o4', 1, 'multiple_choice', 'Wave 4 -- Dependencies: the payment provider is slow, the notification service is down, and retries from every caller are compounding into a storm. What holds the line?', '{"question":"A slow payment provider, a dead notification service, and a retry storm. What holds the line?","options":[{"id":"a","text":"Circuit breakers open against the failing dependencies, timeouts and retry budgets with backoff and jitter stop retries from compounding, and bulkheads keep the failures from starving unrelated request paths"},{"id":"b","text":"Retry every failed call immediately and as many times as needed"},{"id":"c","text":"Remove timeouts so slow calls are never prematurely cut off"},{"id":"d","text":"Route all traffic through a single shared connection pool so failures are easier to observe in one place"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-12-o5-c1', 'mission-be-distributed-systems-12-o5', 1, 'multiple_choice', 'Wave 5 -- Region: an entire region goes dark, DNS reroutes traffic to the survivors, whose caches are cold, right as recovery traffic surges back in. What holds the line?', '{"question":"Full region loss, DNS rerouting, cold caches in the surviving region, and a recovery traffic spike. What holds the line?","options":[{"id":"a","text":"A tested DNS failover shifts traffic to healthy regions, caches are warmed proactively (or requests are ramped gradually) rather than hit cold all at once, and the recovery surge is throttled back up instead of released in full immediately"},{"id":"b","text":"Wait for the failed region to come back on its own before doing anything"},{"id":"c","text":"Route all recovery traffic back at full volume the instant DNS updates"},{"id":"d","text":"Serve every request from cache regardless of staleness until the cache naturally warms"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-be-distributed-systems-12-o6-c1', 'mission-be-distributed-systems-12-o6', 1, 'boss_encounter', 'All five waves are live at once. State the one prioritization principle that decides what gets attention first when everything is failing and nothing can wait.', '{"stages":[{"objectiveRef":"mission-be-distributed-systems-12-o1","label":"Wave 1 -- Traffic"},{"objectiveRef":"mission-be-distributed-systems-12-o2","label":"Wave 2 -- Data"},{"objectiveRef":"mission-be-distributed-systems-12-o3","label":"Wave 3 -- Messaging"},{"objectiveRef":"mission-be-distributed-systems-12-o4","label":"Wave 4 -- Dependencies"},{"objectiveRef":"mission-be-distributed-systems-12-o5","label":"Wave 5 -- Region"}],"task":"Having held every individual wave, state the principle that governs all of them at once: protect the SLOs of the city''s critical functions first, in order of citizen impact -- not in the order the failures happened to arrive, and not by chasing whichever alert is loudest. There is no architecture where nothing fails. There is only one that keeps failing safely, and keeps its promises to the people depending on it, while it does."}'::jsonb, '{"requiredObjectiveIds":["mission-be-distributed-systems-12-o1","mission-be-distributed-systems-12-o2","mission-be-distributed-systems-12-o3","mission-be-distributed-systems-12-o4","mission-be-distributed-systems-12-o5"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be-distributed-systems-01-o1-c1', 'orientation', 'Ask what "acknowledged" should mean: has the leader written it, or has the write actually survived the leader disappearing.', 15, 1),
  ('mission-be-distributed-systems-01-o1-c1', 'solution', 'Only acknowledging after at least one follower confirms the write means the data survives even if the leader dies the instant after -- that''s synchronous replication''s whole point.', 30, 2),

  ('mission-be-distributed-systems-02-o1-c1', 'orientation', 'The dashboard didn''t do anything wrong by reading a replica -- the mistake was trusting a replica for something time-sensitive at all.', 15, 1),
  ('mission-be-distributed-systems-02-o1-c1', 'solution', 'Route latency-sensitive, must-be-current reads to the leader (or track a known write position and wait for the replica to catch up to it); reserve replicas for reads that can tolerate being a little behind.', 30, 2),

  ('mission-be-distributed-systems-03-o1-c1', 'orientation', 'The old leader isn''t malicious -- it just doesn''t know it''s stale. What would make every write path itself reject it?', 15, 1),
  ('mission-be-distributed-systems-03-o1-c1', 'solution', 'A fencing token or epoch number, checked on every write, rejects any write coming from a leader whose epoch is no longer current -- the stale leader simply can''t get a write accepted anymore.', 30, 2),

  ('mission-be-distributed-systems-04-o1-c1', 'orientation', 'A good shard key spreads load regardless of *when* or *in what order* records are created.', 15, 1),
  ('mission-be-distributed-systems-04-o1-c1', 'solution', 'A high-cardinality, evenly-distributed key like a hashed citizen id spreads writes across shards no matter when an enrollment event happens; date-based keys concentrate load on whichever shard "today" maps to.', 30, 2),

  ('mission-be-distributed-systems-05-o1-c1', 'orientation', 'Ask what breaks if each case is stale for even one second, versus what breaks if it''s stale for five minutes.', 15, 1),
  ('mission-be-distributed-systems-05-o1-c1', 'solution', 'The opt-out needs strong consistency -- any staleness is a real harm. The leaderboard can be eventually consistent -- staleness there is invisible to anyone who matters.', 30, 2),

  ('mission-be-distributed-systems-06-o1-c1', 'orientation', 'PACELC''s "Else" branch is specifically about the no-partition case -- what does it say happens there?', 15, 1),
  ('mission-be-distributed-systems-06-o1-c1', 'solution', 'Even with no partition, waiting for more replicas to confirm a write (stronger consistency) costs latency -- that tradeoff exists all the time, not just during a partition, which is exactly what PACELC adds to CAP.', 30, 2),

  ('mission-be-distributed-systems-07-o1-c1', 'orientation', 'The danger isn''t retrying. It''s retrying a request whose effect isn''t safe to apply twice.', 15, 1),
  ('mission-be-distributed-systems-07-o1-c1', 'solution', 'An idempotency key makes a retried request safe regardless of whether the first attempt actually landed -- the server can recognize and no-op a duplicate instead of double-processing it.', 30, 2),

  ('mission-be-distributed-systems-08-o1-c1', 'orientation', 'Lease expiry alone only stops the lock from being held forever -- it doesn''t stop the original holder from acting after it wakes back up.', 15, 1),
  ('mission-be-distributed-systems-08-o1-c1', 'solution', 'A fencing token, required on every protected write and checked against the current token, rejects the stale process''s write even after it wakes up believing it still holds the lock.', 30, 2),

  ('mission-be-distributed-systems-09-o1-c1', 'orientation', 'Think about what happens when two nodes each have an honest but different view of who else is reachable right now.', 15, 1),
  ('mission-be-distributed-systems-09-o1-c1', 'solution', 'Because messages can be delayed or lost, different nodes can reasonably believe different things about who''s alive -- without an explicit majority/quorum step, more than one node can conclude, in good faith, that it''s the leader.', 30, 2),

  ('mission-be-distributed-systems-10-o1-c1', 'orientation', 'Near-zero downtime rules out any approach where recovery takes even a short pause.', 15, 1),
  ('mission-be-distributed-systems-10-o1-c1', 'solution', 'Active-active keeps both regions serving real traffic all the time, so losing one is invisible to users -- the tradeoff the team is explicitly willing to pay for is solving cross-region write conflicts.', 30, 2),

  ('mission-be-distributed-systems-11-o1-c1', 'orientation', 'One number is about data you''re willing to lose. The other is about time you''re willing to be down. Match each phrase to its number.', 15, 1),
  ('mission-be-distributed-systems-11-o1-c1', 'solution', 'RPO (Recovery Point Objective) = 30 seconds of acceptable data loss; RTO (Recovery Time Objective) = 2 minutes of acceptable downtime.', 30, 2),

  ('mission-be-distributed-systems-12-o1-c1', 'orientation', 'Three separate problems are stacked here: too much traffic, one endpoint absorbing it, and pools running out. Each needs its own answer.', 20, 1),
  ('mission-be-distributed-systems-12-o1-c1', 'solution', 'Shed and rate-limit at the edge, cache the hot endpoint where correctness allows it, and let pool exhaustion apply real backpressure instead of unbounded queuing.', 35, 2),

  ('mission-be-distributed-systems-12-o2-c1', 'orientation', 'A tested failover procedure and a defined conflict-resolution rule both need to already exist before this wave hits -- this is where they get used.', 20, 1),
  ('mission-be-distributed-systems-12-o2-c1', 'solution', 'Promote via the tested procedure, fence the old primary immediately, and resolve conflicting writes with the system''s defined rule rather than an arbitrary, after-the-fact choice.', 35, 2),

  ('mission-be-distributed-systems-12-o3-c1', 'orientation', 'Each symptom maps to one specific messaging-system defense you''ve already learned this Act -- idempotency, a dead-letter path, and horizontal scale.', 20, 1),
  ('mission-be-distributed-systems-12-o3-c1', 'solution', 'Idempotent consumers absorb duplicates, a dead-letter queue isolates the poison message instead of blocking the partition, and scaling consumers works down the lag -- all of it designed to survive a rebalance without a human in the loop.', 35, 2),

  ('mission-be-distributed-systems-12-o4-c1', 'orientation', 'The retry storm is the dangerous part -- what stops retries from making a slow dependency worse instead of better?', 20, 1),
  ('mission-be-distributed-systems-12-o4-c1', 'solution', 'Circuit breakers stop calling the failing dependency, backoff-and-jitter retry budgets prevent compounding storms, and bulkheads keep the damage from spreading to unrelated request paths.', 35, 2),

  ('mission-be-distributed-systems-12-o5-c1', 'orientation', 'The recovery traffic spike is its own failure mode, separate from the region loss itself -- a cold cache hit at full volume can cause a second outage.', 20, 1),
  ('mission-be-distributed-systems-12-o5-c1', 'solution', 'Tested DNS failover redirects traffic, caches are warmed or traffic is ramped gradually instead of released at full volume immediately, and the recovery surge is throttled back up rather than dumped all at once.', 35, 2),

  ('mission-be-distributed-systems-12-o6-c1', 'orientation', 'Every wave you just held had one thing in common in how you decided what to fix first.', 25, 1),
  ('mission-be-distributed-systems-12-o6-c1', 'solution', 'Protect the SLOs that matter most to citizens first, ranked by impact, not by arrival order or alert volume -- there is no architecture where nothing fails, only one that fails safely while keeping its promises.', 40, 2);
